(async () => {
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const out = {};
  try {
    // ① 首页上的入口与说明
    out.heroText = document.querySelector('h1')?.parentElement?.innerText?.split('\n').slice(0, 6).join(' / ') || null;
    out.heroLinks = [...document.querySelectorAll('a')].map((a) => a.textContent.trim()).filter((t) => t && (t.includes('工具箱') || t.includes('创建项目')));

    // ② 点「打开工具箱」
    const go = [...document.querySelectorAll('a')].find((a) => a.textContent.includes('打开工具箱'));
    out.hasToolboxCta = !!go;
    go?.click();
    await sleep(3400);
    out.path = location.pathname;

    // ③ 工具箱页的导航：服务器版应该保留全站入口（能回首页/项目）
    out.navInToolbox = [...document.querySelectorAll('header a')].map((a) => a.textContent.trim());
    out.hasHomeLink = [...document.querySelectorAll('header a')].some((a) => a.getAttribute('href') === '/');
    out.hasProjectsLink = [...document.querySelectorAll('header a')].some((a) => (a.getAttribute('href') || '').includes('/projects'));

    // ④ 回首页试试
    const home = [...document.querySelectorAll('header a')].find((a) => a.getAttribute('href') === '/');
    home?.click();
    await sleep(3000);
    out.backHome = location.pathname;
  } catch (e) {
    out.error = String(e && e.message ? e.message : e);
  }
  return JSON.stringify(out);
})()
